// Narrow reader for the static indexed meshes generated by make_cloud_pad.py.
async function cloudPadFromGLB(T,bytes){
  const header=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);
  if(header.getUint32(0,true)!==0x46546c67 || header.getUint32(4,true)!==2)throw Error('Invalid GLB');
  const jsonSize=header.getUint32(12,true);
  const asset=JSON.parse(new TextDecoder().decode(bytes.subarray(20,20+jsonSize)));
  const binStart=bytes.byteOffset+28+jsonSize;
  function attribute(id){
    const a=asset.accessors[id],v=asset.bufferViews[a.bufferView];
    const Type={5126:Float32Array,5123:Uint16Array,5125:Uint32Array}[a.componentType];
    const width={SCALAR:1,VEC3:3,VEC2:2}[a.type];
    if(!Type||!width||v.byteStride)throw Error('Unexpected pad attribute');
    return new T.BufferAttribute(new Type(bytes.buffer,binStart+(v.byteOffset||0)+(a.byteOffset||0),width*a.count),width);
  }
  const maps=await Promise.all((asset.images||[]).map(async image=>{
    const view=asset.bufferViews[image.bufferView];
    const encoded=new Uint8Array(bytes.buffer,binStart+(view.byteOffset||0),view.byteLength);
    const blob=new Blob([encoded],{type:image.mimeType});
    const url=URL.createObjectURL(blob);
    try{
      const img=new Image();img.src=url;await img.decode();
      const canvas=document.createElement('canvas');canvas.width=img.width;canvas.height=img.height;
      canvas.getContext('2d').drawImage(img,0,0);
      const map=new T.CanvasTexture(canvas);map.colorSpace=T.SRGBColorSpace;
      return map;
    }finally{URL.revokeObjectURL(url);}
  }));
  const materials=asset.materials.map(m=>{
    const p=m.pbrMetallicRoughness;
    return new T.MeshStandardMaterial({name:m.name,map:p.baseColorTexture?maps[asset.textures[p.baseColorTexture.index].source]:null,color:new T.Color().fromArray(p.baseColorFactor||[1,1,1]),roughness:p.roughnessFactor??1,metalness:p.metallicFactor??1});
  });
  const root=new T.Group();
  for(const nodeId of asset.scenes[asset.scene].nodes){
    const node=asset.nodes[nodeId],part=new T.Group();
    if(node.translation)part.position.fromArray(node.translation);
    if(node.rotation)part.quaternion.fromArray(node.rotation);
    if(node.scale)part.scale.fromArray(node.scale);
    part.name=node.name;root.add(part);
    for(const p of asset.meshes[node.mesh].primitives){
      const geometry=new T.BufferGeometry();
      geometry.setIndex(attribute(p.indices));geometry.setAttribute('position',attribute(p.attributes.POSITION));geometry.setAttribute('normal',attribute(p.attributes.NORMAL));
      if(p.attributes.TEXCOORD_0!==undefined){
        const source=attribute(p.attributes.TEXCOORD_0),uv=source.clone();
        for(let i=0;i<uv.count;i++)uv.setY(i,1-source.getY(i));
        geometry.setAttribute('uv',uv);
      }
      part.add(new T.Mesh(geometry,materials[p.material]));
    }
  }
  return root;
}
if(typeof module!=='undefined')module.exports=cloudPadFromGLB;
